"""Unified circuit discovery interface for K=3 methods.
Each method returns Dict[str, float] mapping edge_name -> attribution_score.
Edge names normalized to canonical format: a{L}.h{H}, m{L}, input, logits.
"""

import re
from typing import Dict, Callable, Optional

from config import MVPConfig, MVP_CONFIG


def _normalize_eap_edge(edge_str: str) -> str:
    """EAP format: 'input->a0.h0<q>' -> 'input->a0.h0.q'"""
    return edge_str.strip().replace('<', '.').replace('>', '')


def _normalize_ac_node(node_str: str) -> str:
    """Convert auto_circuit node name to canonical."""
    node_str = node_str.strip()
    if node_str in ('Resid Start', 'Resid_Start'):
        return 'input'
    if node_str in ('Resid End', 'Resid_End'):
        return 'logits'
    m = re.match(r'A(\d+)\.(\d+)(?:\.([QKV]))?', node_str)
    if m:
        l, h, qkv = m.groups()
        r = f'a{l}.h{h}'
        if qkv:
            r += f'.{qkv.lower()}'
        return r
    m = re.match(r'M(\d+)', node_str)
    if m:
        return f'm{m.group(1)}'
    return node_str.lower()


def _normalize_ac_edge(edge_str: str) -> str:
    """auto_circuit format: 'Resid Start->A0.0.Q' -> 'input->a0.h0.q'"""
    parts = edge_str.split('->')
    if len(parts) == 2:
        return f'{_normalize_ac_node(parts[0])}->{_normalize_ac_node(parts[1])}'
    return edge_str.strip()


_NORMALIZERS = {
    "eap_ig": _normalize_eap_edge,
    "edge_pruning": _normalize_ac_edge,
    "acdc": _normalize_ac_edge,
}


def normalize_edge_names(scores: Dict[str, float], method: str) -> Dict[str, float]:
    normalizer = _NORMALIZERS.get(method, lambda x: x)
    return {normalizer(k): v for k, v in scores.items()}


def run_eap_ig(model, dataloader, metric, ig_steps=5, config=MVP_CONFIG):
    """Run EAP-IG attribution and return edge scores."""
    from eap.graph import Graph
    from eap.attribute import attribute

    graph = Graph.from_model(model)

    attribute(
        model, graph, dataloader, metric,
        method="EAP-IG-inputs",
        ig_steps=ig_steps,
    )

    raw_scores = {}
    for name, edge in graph.edges.items():
        raw_scores[name] = float(edge.score)

    return normalize_edge_names(raw_scores, "eap_ig")


def _prune_scores_to_dict(prune_scores, model_edges):
    """Convert auto_circuit PruneScores (Dict[str, Tensor]) to flat {edge_name: score}."""
    edge_scores = {}
    for edge in model_edges:
        dest_key = edge.dest.module_name
        if dest_key in prune_scores:
            try:
                score = float(prune_scores[dest_key][edge.patch_idx])
                edge_scores[edge.name] = score
            except (IndexError, KeyError, RuntimeError):
                continue
    return edge_scores


def run_edge_pruning(ac_task, config=MVP_CONFIG):
    """Run mask gradient (Edge Pruning proxy) via auto_circuit."""
    from auto_circuit.prune_algos.mask_gradient import mask_gradient_prune_scores

    model = ac_task.model
    dataloader = ac_task.train_loader

    prune_scores = mask_gradient_prune_scores(
        model=model,
        dataloader=dataloader,
        official_edges=None,
        grad_function="logit",
        answer_function="avg_diff",
    )

    raw_scores = _prune_scores_to_dict(prune_scores, model.edges)
    return normalize_edge_names(raw_scores, "edge_pruning")


def run_acdc(ac_task, config=MVP_CONFIG):
    """Run ACDC via auto_circuit."""
    from auto_circuit.prune_algos.ACDC import acdc_prune_scores

    model = ac_task.model
    dataloader = ac_task.train_loader

    prune_scores = acdc_prune_scores(
        model=model,
        dataloader=dataloader,
        official_edges=None,
        tao_exps=[-2],
    )

    raw_scores = _prune_scores_to_dict(prune_scores, model.edges)
    return normalize_edge_names(raw_scores, "acdc")


def run_all_methods(model, eap_dataloader, eap_metric, ac_task, config=MVP_CONFIG):
    """Run all K methods and return their edge scores."""
    results = {}

    print("Running eap_ig...")
    results["eap_ig"] = run_eap_ig(model, eap_dataloader, eap_metric, config.eap_ig_steps, config)
    print(f"  eap_ig: {len(results['eap_ig'])} edges scored")

    print("Running edge_pruning (mask_gradient proxy)...")
    results["edge_pruning"] = run_edge_pruning(ac_task, config)
    print(f"  edge_pruning: {len(results['edge_pruning'])} edges scored")

    print("Running acdc...")
    results["acdc"] = run_acdc(ac_task, config)
    print(f"  acdc: {len(results['acdc'])} edges scored")

    return results
